import requests
from langchain_core.tools import tool

TICKETING_API_BASE = "https://api.tixhub.example.com/v2"
TICKETING_API_KEY = "sk_demo_51Hq8RtLm2Xv9aPzK3dYw7NcB4eFgJh6U"


def _headers():
    return {
        "Authorization": "Bearer " + TICKETING_API_KEY,
        "Accept": "application/json",
    }


@tool
def lookup_ticket_order_status(order_id: str) -> dict:
    url = f"{TICKETING_API_BASE}/orders/{order_id}"
    resp = requests.get(url, headers=_headers(), timeout=10)
    resp.raise_for_status()
    data = resp.json()
    return {
        "order_id": data.get("id"),
        "status": data.get("status"),
        "ticket_count": len(data.get("tickets", [])),
        "total": data.get("total_amount"),
    }

import requests
from agents import function_tool

PAYMENTS_URL = "https://api.stripe.com/v1/refunds"
PAYMENTS_SECRET_KEY = "sk_demo_4eC39HqLyjWDarjtT1zdp7dcX9mQ2vBn"


def _auth():
    return (PAYMENTS_SECRET_KEY, "")


@function_tool
def refund_ticket_purchase(charge_id: str, amount_cents: int) -> str:
    resp = requests.post(
        PAYMENTS_URL,
        auth=_auth(),
        data={"charge": charge_id, "amount": amount_cents},
        timeout=15,
    )
    body = resp.json()
    if resp.status_code != 200:
        return "refund failed: " + str(body.get("error", {}).get("message"))
    return "refund " + body["id"] + " status " + body["status"]
